import glob, os
from openpyxl import load_workbook

path = "budget.xlsx"
if not os.path.exists(path):
    cands = sorted(glob.glob("**/budget.xlsx", recursive=True))
    if cands:
        path = cands[0]

wb = load_workbook(path, data_only=True)
print("file:", os.path.abspath(path))
print("sheets:", wb.sheetnames)
for ws in wb.worksheets:
    print("=== sheet:", ws.title, "dims:", ws.dimensions, "max_row:", ws.max_row, "max_col:", ws.max_column)
    for row in ws.iter_rows():
        vals = [(c.coordinate, c.value) for c in row if c.value is not None]
        if vals:
            print(vals)

